  `dist_inviter_user_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '直推邀请人用户编码',
  `dist_inviter_commission_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '直推邀请人分佣金额',
  `dist_superior_inviter_user_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '上级邀请人用户编码',
  `dist_superior_commission_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '上级邀请人分佣金额（付费5%）',
  `dist_commission_applied_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NO' COMMENT '分佣是否已计入汇总 YES-是 NO-否',
  `dist_settled_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NO' COMMENT '是否结算完成 YES-是 NO-否',
  `dist_settle_applied_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NO' COMMENT '是否申请结算 YES-是 NO-否',
  `dist_in_service_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NO' COMMENT '是否在服务期内 YES-是 NO-否',
  `dist_service_period_end_at` datetime NULL DEFAULT NULL COMMENT '服务期结束时间',
  `dist_settled_at` datetime NULL DEFAULT NULL COMMENT '实际结算时间',
  `dist_settle_batch_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '结算批次',
  `dist_settle_batch_status_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '是否结算完成',
  `dist_test_status_code` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '是否测试数据 0否 1是',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_dist_bill_settle_od_gd`(`td_od_gd_code` ASC) USING BTREE,
  INDEX `idx_dist_bill_settle_payer`(`dist_payer_user_code` ASC, `dist_settled_status_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户账单结算记录' ROW_FORMAT = DYNAMIC;

