  UNIQUE INDEX `im_message_code`(`im_message_code` ASC) USING BTREE,
  INDEX `idx_conversation`(`im_message_conversation_code` ASC, `create_time` DESC) USING BTREE,
  INDEX `idx_to_user`(`im_message_to_user_code` ASC, `im_message_read_status_code` ASC) USING BTREE
