  `td_gd_hidden_status_code` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '是否隐藏：1是 0否（移动端不展示隐藏商品）',
