INSERT INTO `ai_chat_message` VALUES ('2070738447561023490', NULL, NULL, NULL, '2026-06-27 13:18:13', NULL, '2026-06-27 13:18:13', NULL, '0', '2070738447572971520', '2067915116564721664', 'assistant', '您好，我是客服笑笑。通过平台赚钱分两种：\n\n1. **推荐会员**：别人通过您购买会员，您拿75%会员费。\n2. **红娘服务**：帮客户安排见面或包结婚，您拿75%服务费。\n\n快速起步：先推荐朋友买会员，同时入驻平台绑定企业。官网：example.com\n\n需要我教您怎么入驻吗？', 40);
